<h1 class="h4 mb-3">Nueva ruta de ronda</h1><form method="post" action="<?= e(url('/panel/rondas/rutas')) ?>" class="card card-body" style="max-width:760px"><?= csrf_field() ?><label class="form-label">Nombre</label><input class="form-control mb-3" name="name" required placeholder="Ronda nocturna planta 1"><label class="form-label">Descripción</label><textarea class="form-control mb-3" name="description" rows="2"></textarea><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Frecuencia</label><select class="form-select" name="frequency"><option value="manual">Manual</option><option value="diaria">Diaria</option><option value="semanal">Semanal</option><option value="mensual">Mensual</option></select></div><div class="col-md-6"><label class="form-label">Duración esperada (minutos)</label><input class="form-control" name="expected_minutes" type="number" min="1"></div></div><label class="form-label">Puntos, en orden</label><div class="list-group mb-3"><?php foreach ($points as $p): ?><label class="list-group-item"><input class="form-check-input me-2" type="checkbox" name="points[]" value="<?= e($p['uuid']) ?>"> <strong><?= e($p['code']) ?></strong> · <?= e($p['name']) ?></label><?php endforeach; ?></div><label class="form-label">Asignar a guardias</label><div class="list-group mb-3"><?php foreach ($users as $u): ?><label class="list-group-item"><input class="form-check-input me-2" type="checkbox" name="users[]" value="<?= e($u['uuid']) ?>"><?= e($u['name']) ?> <span class="small text-body-secondary">· <?= e($u['role_name']) ?></span></label><?php endforeach; ?></div><button class="btn btn-primary">Crear ruta</button></form>
